-- DevModels gallery on the flat dev map 929 (AdtDevMap, .teleport DevModels): one test NPC per client creature model that
-- is not in stock 3.3.5a, plus a hand-picked list, for previewing models in game. Each group (the hand-picked list, then the
-- model folder's first letter A-Z) is its own phase on the same spot; the Gallery Guide (9429001) switches the player's phase
-- through its gossip menu. GM mode (.gm on) sees every phase at once and loads ~2000 models, so use .gm off here.
-- Models without a client display id get streamed creaturemodeldata_dbc/creaturedisplayinfo_dbc rows (990101+); they need the
-- AscensionCompat stream change (separate PR) to render. Models that hang or crash the client are left out.
-- Ids: creature_template/creature 9420001-9422785 + guide 9429001 (guid 9429001), displays 990101-990949 and 139112, models 990101-990499.
DELETE FROM `creature` WHERE `map` = 929 AND (`guid` BETWEEN 9420001 AND 9422785 OR `guid` = 9429001);
DELETE FROM `creature_template_addon` WHERE `entry` BETWEEN 9420001 AND 9422785;
DELETE FROM `creature_template_movement` WHERE `CreatureId` BETWEEN 9420001 AND 9422785;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 9420001 AND 9422785 OR `CreatureID` = 9429001;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 9420001 AND 9422785 OR `entry` = 9429001;
DELETE FROM `gossip_menu_option` WHERE `MenuID` = 9429001;
DELETE FROM `gossip_menu` WHERE `MenuID` = 9429001;
DELETE FROM `smart_scripts` WHERE `entryorguid` = 9429001 AND `source_type` = 0;
DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` BETWEEN 990101 AND 990949 OR `ID` = 139112;
DELETE FROM `creaturemodeldata_dbc` WHERE `ID` BETWEEN 990101 AND 990499;
